#!/bin/sh
# Phase 0b judging + Phase 0c Q38 regeneration. Waits for phase0b_gen. Generation first, then judging (never both on the GPU).
OMLX_URL=${OMLX_URL:-$(cat "$HOME/.config/kafka-sre-llm/omlx_url")}
while [ ! -e runs/v3/logs/p0b_gen.done ]; do sleep 60; done
W=work/v3/judge; L=runs/v3/logs/p0bc_judge.log
cp -n work/v3/ans_rag_k6.jsonl work/v3/ans_rag_newidx.jsonl
scripts/run_guarded.py --log runs/v3/logs/p0c_q38.log --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python scripts/rag_answers.py answer --model runs/v1/base27b --questions work/v3/questions_q38.jsonl --packs work/v3/rag_packs_newidx.json --k k6 --index work/v3/chunks.jsonl --out work/v3/ans_rag_newidx_q38.jsonl || exit 1
echo P0C_GEN_DONE >> runs/v3/logs/p0c_gen.done
.venv/bin/python -c "import httpx,os;httpx.post('$OMLX_URL/v1/chat/completions',headers={'Authorization':'Bearer '+os.environ['JUDGE_API_KEY']},timeout=1500,json={'model':'GLM-5.3-Flash-oQ8e-mtp','messages':[{'role':'user','content':'hi'}],'max_tokens':5}).raise_for_status()"
Q=eval/questions_real.jsonl
.venv/bin/python scripts/mk_h2h.py work/v3/ans_rag_k6.jsonl work/v3/ans_rag_strict.jsonl $W/h2h_strict.answers.jsonl $Q
.venv/bin/python scripts/mk_h2h.py work/v3/ans_rag_k6.jsonl work/v3/ans_rag_dsexp.jsonl $W/h2h_dsexp.answers.jsonl $Q
.venv/bin/python scripts/mk_h2h.py work/v3/ans_rag_k6.jsonl work/v3/ans_rag_newidx_q38.jsonl $W/h2h_newidx_q38.answers.jsonl work/v3/questions_q38.jsonl
scripts/run_guarded.py --log $L --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python eval/compare.py --model runs/v1/base27b --adapter none --questions eval/questions_real.jsonl --max-tokens 2048 --cache $W/h2h_strict.answers.jsonl --out $W/results_h2h_strict_p1.jsonl --judge-url $OMLX_URL/v1 --judge-model GLM-5.3-Flash-oQ8e-mtp --judge-extra-body '{"max_tokens": 32768}' --judge-concurrency 3 --judge-cache $W/judge_h2h_strict_p1.cache.jsonl || exit 1
scripts/run_guarded.py --log $L --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python eval/compare.py --model runs/v1/base27b --adapter none --questions eval/questions_real.jsonl --max-tokens 2048 --cache $W/h2h_strict.answers.jsonl --out $W/results_h2h_strict_p2.jsonl --judge-url $OMLX_URL/v1 --judge-model GLM-5.3-Flash-oQ8e-mtp --judge-extra-body '{"max_tokens": 32768}' --judge-concurrency 3 --judge-cache $W/judge_h2h_strict_p2.cache.jsonl --judge-flip || exit 1
scripts/run_guarded.py --log $L --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python eval/compare.py --model runs/v1/base27b --adapter none --questions eval/questions_real.jsonl --max-tokens 2048 --cache $W/h2h_dsexp.answers.jsonl --out $W/results_h2h_dsexp_p1.jsonl --judge-url $OMLX_URL/v1 --judge-model GLM-5.3-Flash-oQ8e-mtp --judge-extra-body '{"max_tokens": 32768}' --judge-concurrency 3 --judge-cache $W/judge_h2h_dsexp_p1.cache.jsonl || exit 1
scripts/run_guarded.py --log $L --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python eval/compare.py --model runs/v1/base27b --adapter none --questions eval/questions_real.jsonl --max-tokens 2048 --cache $W/h2h_dsexp.answers.jsonl --out $W/results_h2h_dsexp_p2.jsonl --judge-url $OMLX_URL/v1 --judge-model GLM-5.3-Flash-oQ8e-mtp --judge-extra-body '{"max_tokens": 32768}' --judge-concurrency 3 --judge-cache $W/judge_h2h_dsexp_p2.cache.jsonl --judge-flip || exit 1
scripts/run_guarded.py --log $L --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python eval/compare.py --model runs/v1/base27b --adapter none --questions work/v3/questions_q38.jsonl --max-tokens 2048 --cache $W/h2h_newidx_q38.answers.jsonl --out $W/results_h2h_newidx_q38_p1.jsonl --judge-url $OMLX_URL/v1 --judge-model GLM-5.3-Flash-oQ8e-mtp --judge-extra-body '{"max_tokens": 32768}' --judge-concurrency 3 --judge-cache $W/judge_h2h_newidx_q38_p1.cache.jsonl || exit 1
scripts/run_guarded.py --log $L --heartbeat runs/v3/HEARTBEAT.md --stall-min 60 -- .venv/bin/python eval/compare.py --model runs/v1/base27b --adapter none --questions work/v3/questions_q38.jsonl --max-tokens 2048 --cache $W/h2h_newidx_q38.answers.jsonl --out $W/results_h2h_newidx_q38_p2.jsonl --judge-url $OMLX_URL/v1 --judge-model GLM-5.3-Flash-oQ8e-mtp --judge-extra-body '{"max_tokens": 32768}' --judge-concurrency 3 --judge-cache $W/judge_h2h_newidx_q38_p2.cache.jsonl --judge-flip || exit 1
echo P0BC_JUDGE_DONE >> runs/v3/logs/p0bc_judge.done
